INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Bone Structure & Remodelling','easy','mcq','Which cell type is primarily responsible for bone matrix synthesis and mineralisation?','["A. Osteoclast","B. Osteoblast","C. Osteocyte","D. Chondroblast"]','B','Osteoblasts synthesise the organic matrix (osteoid) of bone, including type I collagen, and orchestrate its mineralisation with hydroxyapatite crystals. Osteoclasts resorb bone; osteocytes are mature embedded cells that sense mechanical load.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Bone Structure & Remodelling','easy','mcq','Wolff''''s law states that bone remodels in response to which stimulus?','["A. Hormonal signals from the parathyroid gland","B. Mechanical forces and stresses applied to it","C. Systemic vitamin D levels","D. Blood calcium concentration"]','B','Wolff''''s law states that bone adapts its structure in response to the mechanical loads placed upon it. Increased loading leads to increased bone deposition, while disuse leads to resorption. This principle underpins exercise recommendations for osteoporosis prevention.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Bone Structure & Remodelling','medium','mcq','Which of the following best describes the role of RANK-RANKL signalling in bone remodelling?','["A. RANKL on osteoclasts activates RANK on osteoblasts, promoting bone formation","B. RANK on osteoblasts inhibits osteoclast differentiation when bound to RANKL","C. RANKL is exclusively secreted by T lymphocytes and has no role in normal remodelling","D. RANKL on osteoblasts activates RANK on osteoclast precursors, promoting osteoclastogenesis"]','D','RANKL (receptor activator of NF-κB ligand) is expressed on osteoblasts and stromal cells. It binds RANK on osteoclast precursors, driving their differentiation and activation. Osteoprotegerin (OPG), also secreted by osteoblasts, acts as a decoy receptor for RANKL, inhibiting osteoclastogenesis.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Bone Structure & Remodelling','medium','mcq','An osteoblast that becomes surrounded by and embedded in the bone matrix it has secreted is called a(n):','["A. Osteocyte","B. Osteoclast","C. Periosteal cell","D. Chondrocyte"]','A','When osteoblasts become entrapped within the mineralised matrix they produce, they differentiate into osteocytes. Osteocytes reside in lacunae and communicate via canaliculi, acting as mechanosensors that regulate bone remodelling.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Bone Structure & Remodelling','medium','mcq','Which enzyme secreted by osteoclasts is directly responsible for demineralisation of bone during resorption?','["A. Alkaline phosphatase","B. Tartrate-resistant acid phosphatase (TRAP)","C. Carbonic anhydrase II","D. Collagenase"]','C','Osteoclasts express carbonic anhydrase II, which generates H+ ions that are pumped into the resorption lacuna (Howship''''s lacuna) to dissolve hydroxyapatite. TRAP is a marker of osteoclast activity but does not directly demineralise bone; collagenase degrades organic matrix after demineralisation.','universal',true,'{year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Bone Structure & Remodelling','medium','mcq','The organic component of bone matrix that provides tensile strength is primarily:','["A. Hydroxyapatite","B. Type II collagen","C. Type I collagen","D. Chondroitin sulphate"]','C','Bone matrix consists of approximately 35% organic material, of which 90-95% is type I collagen. This collagen framework provides tensile strength. The inorganic component, hydroxyapatite [Ca10(PO4)6(OH)2], provides compressive strength and rigidity.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Bone Structure & Remodelling','hard','mcq','A patient with Paget''''s disease of bone demonstrates markedly elevated serum alkaline phosphatase. Which of the following best explains this finding?','["A. Osteoblastic activity is greatly increased as bone is rapidly laid down in a disorganised pattern","B. Alkaline phosphatase is released from hyperactive osteoclasts during bone resorption","C. Elevated PTH drives alkaline phosphatase secretion from parathyroid cells","D. Alkaline phosphatase is released from damaged hepatocytes due to bisphosphonate therapy"]','A','In Paget''''s disease, there is dysregulated bone remodelling with massively increased osteoclast and osteoblast activity. Alkaline phosphatase is a product of osteoblast activity and is used as a serum marker of bone formation; elevated levels reflect the intense, disorganised bone formation characteristic of Paget''''s disease.','universal',true,'{year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Bone Structure & Remodelling','hard','mcq','Which of the following correctly describes the structure of a Haversian system (osteon)?','["A. Trabeculae of cancellous bone arranged along lines of stress","B. Flat plates of cortical bone separated by marrow spaces","C. Concentric lamellae of bone matrix surrounding a central (Haversian) canal containing blood vessels and nerves","D. Osteocyte lacunae connected by canaliculi without a central vascular channel"]','C','An osteon (Haversian system) is the structural unit of cortical bone, consisting of concentric lamellae of mineralised collagen surrounding a Haversian canal. The canal contains blood vessels, lymphatics, and nerves. Osteocytes in lacunae connect to each other and to the Haversian canal via canaliculi.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Bone Structure & Remodelling','hard','mcq','Bisphosphonates used to treat osteoporosis act primarily by:','["A. Inhibiting osteoclast activity by disrupting the mevalonate pathway and inducing osteoclast apoptosis","B. Stimulating osteoblast proliferation and collagen synthesis","C. Blocking RANKL binding to RANK on osteoclast precursors","D. Increasing intestinal calcium absorption by mimicking vitamin D action"]','A','Nitrogen-containing bisphosphonates (e.g., alendronate, zoledronate) inhibit farnesyl pyrophosphate synthase in the mevalonate pathway of osteoclasts. This prevents prenylation of signalling proteins, impairing osteoclast function and inducing apoptosis. Denosumab (not bisphosphonates) blocks RANKL.','universal',true,'{year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Bone Structure & Remodelling','easy','mcq','During bone remodelling, which sequence correctly describes the order of events?','["A. Formation → Resorption → Reversal → Quiescence","B. Quiescence → Formation → Resorption → Reversal","C. Reversal → Quiescence → Formation → Resorption","D. Resorption → Reversal → Formation → Quiescence"]','D','The bone remodelling cycle follows the sequence: Activation (osteoclast recruitment) → Resorption (osteoclasts excavate bone) → Reversal (mononuclear cells prepare surface) → Formation (osteoblasts deposit new matrix) → Quiescence. This cycle takes approximately 3-6 months in adult bone.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Cartilage & Connective Tissue','easy','mcq','Which type of cartilage is found at articular surfaces of synovial joints?','["A. Fibrocartilage","B. Elastic cartilage","C. Hyaline cartilage","D. Yellow fibrocartilage"]','C','Hyaline cartilage covers the articular surfaces of synovial joints. It contains type II collagen and proteoglycans (aggrecan) in an abundant ground substance, providing a smooth, low-friction surface ideal for joint movement. It is avascular and relies on diffusion from synovial fluid for nutrition.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Cartilage & Connective Tissue','easy','mcq','Which collagen type predominates in hyaline cartilage?','["A. Type II collagen","B. Type I collagen","C. Type III collagen","D. Type IV collagen"]','A','Type II collagen is the major collagen of hyaline and elastic cartilage, forming a fine meshwork that entraps large proteoglycan aggregates. Type I collagen predominates in bone, skin, tendons, and fibrocartilage. Type IV collagen is found in basement membranes.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Cartilage & Connective Tissue','medium','mcq','Fibrocartilage differs from hyaline cartilage in that it:','["A. Contains chondrocytes within lacunae","B. Is completely avascular and aneural","C. Has a higher content of type I collagen fibres giving greater tensile strength","D. Forms the articular surfaces of all major synovial joints"]','C','Fibrocartilage (e.g., intervertebral discs, menisci, pubic symphysis) contains abundant type I collagen fibres interspersed among a smaller amount of type II collagen and ground substance. This composition confers high tensile strength and resistance to compression and shear forces.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Cartilage & Connective Tissue','medium','mcq','The ground substance of cartilage is primarily composed of:','["A. Hydroxyapatite and calcium phosphate","B. Type I collagen and fibronectin","C. Proteoglycans (aggrecan) and hyaluronic acid","D. Elastin and laminin"]','C','Ground substance of cartilage consists predominantly of aggrecan (a large proteoglycan) bound to hyaluronic acid via link proteins, forming huge aggregates. These aggregates are highly hydrophilic, attracting water and providing compressive resistance. The high water content (70-80%) is essential for nutrient diffusion.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Cartilage & Connective Tissue','medium','mcq','Elastic cartilage, found in the external ear and epiglottis, is distinguished from hyaline cartilage by the presence of:','["A. Type I collagen fibres","B. Calcification within the matrix","C. Abundant elastic fibres containing elastin","D. A periosteum rather than a perichondrium"]','C','Elastic cartilage contains elastic fibres (elastin) in addition to type II collagen, which impart flexibility and the ability to return to original shape after deformation. It is found in the auricle, external auditory canal, epiglottis, and laryngeal cartilages (cuneiform and corniculate).','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Cartilage & Connective Tissue','medium','mcq','Which of the following collagen types forms the basement membranes of blood vessels and epithelial layers?','["A. Type I","B. Type IV","C. Type II","D. Type III"]','B','Type IV collagen forms a network (not fibrillar) structure that is a key structural component of basement membranes throughout the body. It provides support for overlying epithelial and endothelial cells. Mutations in type IV collagen genes cause Alport syndrome.','universal',false,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Cartilage & Connective Tissue','hard','mcq','Ehlers-Danlos syndrome (hypermobile type) is characterised by joint hypermobility and skin hyperextensibility. The primary molecular defect involves:','["A. Mutations in type II collagen genes leading to cartilage degradation","B. Defects in collagen cross-linking or synthesis leading to structurally weak connective tissue","C. Excess RANKL expression causing increased bone resorption","D. Absence of elastin leading to loss of tissue recoil"]','B','Ehlers-Danlos syndromes involve genetic defects in collagen structure, synthesis, or processing (including cross-linking enzymes such as lysyl hydroxylase). This results in mechanically inferior connective tissue with excessive joint laxity, skin extensibility, and fragile blood vessels depending on the subtype.','universal',true,'{year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Cartilage & Connective Tissue','hard','mcq','Proteoglycans in articular cartilage resist compressive loads primarily because:','["A. Their cross-links with type II collagen fibres resist deformation","B. They are mineralised with hydroxyapatite, providing rigidity","C. They directly bind to subchondral bone, distributing load across the joint surface","D. Their highly charged sulphate groups attract water, creating a swelling pressure within the collagen network"]','D','Proteoglycans (primarily aggrecan) bear many negatively charged sulphate and carboxylate groups from glycosaminoglycans (chondroitin sulphate, keratan sulphate). These fixed negative charges attract cations and water (Donnan osmotic pressure), creating a swelling pressure that is constrained by the collagen network, thus resisting compressive loads.','universal',true,'{year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Cartilage & Connective Tissue','hard','mcq','In osteoarthritis, the earliest matrix change observed in articular cartilage is:','["A. Mineralisation of articular cartilage with hydroxyapatite","B. Proliferation of chondrocytes forming chondrons","C. Calcification of the tidemark and subchondral bone sclerosis","D. Loss of proteoglycan content from the superficial zone"]','D','The earliest detectable change in osteoarthritis is the loss of proteoglycans (particularly aggrecan) from the superficial zone of articular cartilage, reflected in reduced staining for glycosaminoglycans. This is followed by fibrillation (surface irregularity), chondrocyte death, and eventual full-thickness cartilage loss.','universal',true,'{year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Cartilage & Connective Tissue','easy','mcq','The perichondrium is a layer of dense connective tissue surrounding cartilage that contains:','["A. Osteoblasts and osteoclasts capable of intramembranous ossification","B. Chondrogenic cells capable of producing new cartilage (appositional growth)","C. Haematopoietic stem cells supplying blood cells to avascular cartilage","D. Mast cells that secrete histamine in response to cartilage injury"]','B','The perichondrium''''s inner layer (chondrogenic layer) contains chondroprogenitor cells that can differentiate into chondroblasts, enabling appositional (peripheral) cartilage growth. The outer fibrous layer is vascularised and provides nutrients. Cartilage itself is avascular, deriving nutrition by diffusion.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Skeletal Muscle Structure','easy','mcq','In a sarcomere, the A band corresponds to:','["A. Only the thin (actin) filaments","B. The entire length of the thick (myosin) filaments, including the region of overlap with actin","C. The zone of actin filaments alone, with no myosin overlap","D. The Z discs at each end of the sarcomere"]','B','The A (anisotropic) band spans the full length of the myosin (thick) filaments and appears dark under polarised light. It includes the zones of actin-myosin overlap and the H zone (central region of myosin only). During contraction, the A band length remains constant as it equals myosin filament length.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Skeletal Muscle Structure','easy','mcq','The functional unit of skeletal muscle contraction is the:','["A. Sarcomere","B. Myofibril","C. Motor unit","D. Muscle fibre"]','A','The sarcomere is the basic contractile unit of striated muscle, defined as the segment between two consecutive Z discs. It contains the interdigitating thick (myosin) and thin (actin) filaments whose sliding generates force. In a relaxed adult skeletal muscle, the sarcomere length is approximately 2.0-2.4 micrometres.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Skeletal Muscle Structure','medium','mcq','A motor unit consists of:','["A. A single skeletal muscle fibre and its blood supply","B. One alpha motor neuron and all the skeletal muscle fibres it innervates","C. All the motor neurons supplying a single muscle","D. The neuromuscular junction plus the adjacent muscle spindle"]','B','A motor unit is the fundamental unit of motor control, comprising one alpha (α) motor neuron and all the skeletal muscle fibres it innervates. All fibres in a motor unit are of the same fibre type and contract simultaneously (all-or-none principle). Small motor units (e.g., extraocular muscles) allow fine motor control; large units (e.g., quadriceps) generate large forces.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Skeletal Muscle Structure','medium','mcq','Titin (connectin) in the sarcomere primarily functions as:','["A. The cross-bridge that generates force during contraction","B. The thin filament regulatory protein that inhibits actin-myosin interaction","C. A structural protein linking actin filaments to the Z disc only","D. An elastic spring that maintains the position of myosin within the sarcomere and provides passive tension"]','D','Titin is the largest known protein and spans from the Z disc to the M line. Its elastic (PEVK) segment acts as a molecular spring that centres myosin filaments within the sarcomere, provides passive tension when the sarcomere is stretched, and returns to resting length during relaxation. Titin mutations cause dilated cardiomyopathy.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Skeletal Muscle Structure','medium','mcq','The I band of the sarcomere:','["A. Contains only thick (myosin) filaments","B. Spans the full width of the A band","C. Is the region of the M line where myosin filaments are cross-linked","D. Contains only thin (actin) filaments and shortens during contraction"]','D','The I (isotropic) band appears light under polarised light and contains only actin (thin) filaments, spanning from the Z disc to where the actin filaments begin to overlap with myosin. During contraction, the I band shortens as actin filaments slide toward the centre of the sarcomere, while the A band length remains unchanged.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Skeletal Muscle Structure','medium','mcq','The T-tubule system in skeletal muscle fibres:','["A. Stores and releases calcium ions during excitation-contraction coupling","B. Transmits action potentials from the sarcolemma to the interior of the muscle fibre","C. Synthesises acetylcholine for release at the neuromuscular junction","D. Forms the sarcoplasmic reticulum cisternae adjacent to the myofibrils"]','B','Transverse (T) tubules are invaginations of the sarcolemma that extend deep into the muscle fibre. They rapidly conduct action potentials from the cell surface to the interior, ensuring near-simultaneous activation of all myofibrils. At each junction of A and I bands, the T-tubule contacts two terminal cisternae of the sarcoplasmic reticulum to form a triad.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Skeletal Muscle Structure','hard','mcq','Which statement correctly describes the structure of the myosin thick filament?','["A. It is a single protein molecule approximately 2 mm in length with one globular head","B. It contains only light meromyosin and lacks enzymatic ATPase activity","C. It is composed of G-actin monomers polymerised into two intertwining strands","D. It consists of 200 myosin molecules with heads projecting outward along its length except at the central bare zone"]','D','Each myosin thick filament is composed of approximately 200-300 myosin II molecules. The tails bundle together to form the backbone; the heads (S1 fragments) project outward at regular intervals in a helical pattern to interact with actin. The central 150 nm is a bare zone devoid of heads where the two halves of the filament are arranged tail-to-tail.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Skeletal Muscle Structure','hard','mcq','In a relaxed sarcomere 2.2 µm long, if the myosin filament is 1.6 µm and each actin filament extends 1.0 µm from the Z disc, the length of the H zone would be:','["A. 0.2 µm","B. 0.6 µm","C. 0.4 µm","D. 0.8 µm"]','B','The H zone is the central region of the A band containing only myosin with no actin overlap. Sarcomere = 2.2 µm, so each half = 1.1 µm from the M line to the Z disc. Actin extends 1.0 µm from Z disc, so it reaches 0.1 µm from the M line on each side. H zone = 1.6 µm (myosin) − 2 × 0.5 µm actin overlap from each end = 0.6 µm. (Alternatively: bare zone = myosin length − 2 × actin overlap = 1.6 − 2(0.5) = 0.6 µm.)','universal',false,'{year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Skeletal Muscle Structure','hard','mcq','Nebulin in skeletal muscle serves as a molecular ruler for:','["A. Determining the length of myosin thick filaments","B. Measuring the inter-filament spacing in the hexagonal lattice","C. Regulating calcium sensitivity of troponin C","D. Setting the length of actin thin filaments within the sarcomere"]','D','Nebulin is a giant protein (~800 kDa) that runs along the length of the thin filament from the Z disc. It acts as a molecular ruler determining the precise length of actin thin filaments (~1 µm), ensuring uniform thin filament lengths across sarcomeres. Mutations in nebulin cause nemaline myopathy.','universal',false,'{year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Skeletal Muscle Structure','easy','mcq','In the hexagonal arrangement of myofilaments, each myosin thick filament is surrounded by how many actin thin filaments?','["A. Two","B. Six","C. Four","D. Eight"]','B','In the overlap region of the sarcomere, the thick and thin filaments are arranged in a hexagonal lattice in which each myosin filament is surrounded by six actin filaments, and each actin filament is shared between three myosin filaments. This arrangement maximises the number of potential cross-bridge interactions.','universal',false,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Muscle Contraction Mechanism','easy','mcq','During skeletal muscle contraction, calcium binds to which protein to initiate cross-bridge cycling?','["A. Troponin C","B. Tropomyosin","C. Troponin I","D. Actin"]','A','Calcium released from the sarcoplasmic reticulum binds to troponin C (the calcium-binding subunit of the troponin complex). This causes a conformational change in the troponin-tropomyosin complex, shifting tropomyosin away from the myosin-binding sites on actin, allowing cross-bridge formation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Muscle Contraction Mechanism','easy','mcq','The power stroke of myosin cross-bridges is powered by:','["A. Hydrolysis of ATP occurring during the stroke itself","B. Release of Pi and ADP from the myosin head that was previously loaded with energy from ATP hydrolysis","C. Influx of calcium ions into the myosin head","D. Hydrolysis of GTP by the myosin head"]','B','ATP is hydrolysed to ADP + Pi before the power stroke, cocking the myosin head into a high-energy configuration. When the myosin head binds actin, Pi is released first (triggering the power stroke), followed by ADP release. This produces the ~10 nm translocation of actin. ATP then binds to detach the myosin head.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Muscle Contraction Mechanism','medium','mcq','Rigor mortis occurs because:','["A. Calcium floods the sarcolemma after death, causing irreversible troponin activation","B. Sarcoplasmic reticulum actively pumps excess calcium, causing muscle hypercontraction","C. Depletion of ATP prevents myosin heads from detaching from actin, locking filaments in a rigor state","D. Acetylcholinesterase activity ceases, causing sustained depolarisation of muscle fibres"]','C','After death, ATP synthesis ceases. Without ATP, myosin heads cannot detach from actin after the power stroke (ATP binding is required for detachment). Muscles become locked in a rigid, contracted state. Rigor mortis begins 2-6 hours after death and resolves 24-48 hours later as autolytic enzymes degrade the contractile proteins.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Muscle Contraction Mechanism','medium','mcq','The role of troponin I (TnI) in the resting skeletal muscle fibre is to:','["A. Bind calcium to trigger contraction","B. Connect tropomyosin to the actin filament backbone","C. Inhibit the interaction between actin and myosin by stabilising the tropomyosin position over myosin-binding sites","D. Directly hydrolyse ATP to power cross-bridge cycling"]','C','Troponin I (inhibitory) stabilises tropomyosin over the myosin-binding sites on actin in the absence of calcium, preventing cross-bridge formation. Troponin C binds calcium; troponin T anchors the complex to tropomyosin. When calcium binds TnC, TnI releases its inhibitory hold, allowing tropomyosin to shift and expose actin binding sites.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Muscle Contraction Mechanism','medium','mcq','During a single cross-bridge cycle, what is the correct order of events?','["A. ATP binding → myosin detachment → ATP hydrolysis → actin binding → power stroke → Pi release","B. Actin binding → power stroke → ATP binding → myosin detachment → ATP hydrolysis → Pi release","C. ATP hydrolysis → actin binding → Pi release → power stroke → ADP release → ATP binding","D. Pi release → power stroke → ADP release → ATP binding → ATP hydrolysis → actin binding"]','C','The cross-bridge cycle: (1) ATP binds myosin head and is hydrolysed to ADP+Pi, cocking the head; (2) cocked head binds actin weakly; (3) Pi release triggers strong actin binding and the power stroke; (4) ADP is released; (5) new ATP binds, causing myosin to detach from actin; the cycle repeats if calcium and ATP are available.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Muscle Contraction Mechanism','medium','mcq','Excitation-contraction coupling in skeletal muscle is mediated by:','["A. Second messenger cAMP opening the ryanodine receptor via protein kinase A phosphorylation","B. Direct mechanical coupling between the voltage-sensing dihydropyridine receptor (DHPR) in the T-tubule and the ryanodine receptor (RyR1) in the SR","C. IP3-mediated calcium release from the sarcoplasmic reticulum triggered by nicotinic receptor activation","D. Direct calcium influx through DHPR channels providing sufficient calcium for contraction"]','B','In skeletal muscle, the dihydropyridine receptor (DHPR/L-type voltage-gated calcium channel) in the T-tubule wall acts as a voltage sensor. Upon depolarisation, it undergoes a conformational change that directly (mechanically) opens the ryanodine receptor 1 (RyR1) in the SR membrane, releasing a flood of calcium into the cytoplasm.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Muscle Contraction Mechanism','hard','mcq','At optimal sarcomere length (approximately 2.0-2.2 µm), maximum force is generated because:','["A. The actin filaments maximally overlap with each other, reducing steric hindrance","B. Titin is fully stretched, adding its passive elastic force to active cross-bridge force","C. The H zone disappears completely, allowing all myosin heads to simultaneously form cross-bridges","D. The number of myosin cross-bridges able to interact with actin sites is at its maximum"]','D','The length-tension relationship of muscle reflects the degree of actin-myosin overlap. At optimal sarcomere length (~2.0-2.2 µm), the maximum number of myosin cross-bridge heads can interact with available actin binding sites, producing peak isometric force. At shorter lengths, actin filaments interfere with each other; at longer lengths, overlap decreases.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Muscle Contraction Mechanism','hard','mcq','Which of the following correctly describes the ''latch state'' seen in smooth muscle but NOT in skeletal muscle?','["A. Cross-bridges cycle rapidly but generate less force per bridge than in skeletal muscle","B. Calcium-independent cross-bridge formation driven by cAMP-dependent phosphorylation","C. Slowly cycling dephosphorylated cross-bridges maintain force with minimal ATP consumption","D. Maximum force generation requiring high intracellular calcium concentrations to be sustained"]','C','The latch state is unique to smooth muscle. After initial contraction (myosin phosphorylated by MLCK), some cross-bridges become dephosphorylated by myosin phosphatase but remain attached to actin in a slowly cycling ''latch bridge'' state. This allows sustained force maintenance with very low ATP consumption, important for tonic smooth muscle contraction (e.g., vascular tone).','universal',false,'{year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Muscle Contraction Mechanism','hard','mcq','Malignant hyperthermia is a life-threatening condition triggered by volatile anaesthetics and succinylcholine, caused by:','["A. Irreversible inhibition of acetylcholinesterase causing sustained neuromuscular junction depolarisation","B. Loss-of-function mutations in DHPR preventing T-tubule action potential transmission","C. Excessive mitochondrial uncoupling caused by volatile anaesthetics in susceptible individuals","D. Gain-of-function mutations in RyR1 leading to uncontrolled calcium release from the sarcoplasmic reticulum"]','D','Malignant hyperthermia is caused by gain-of-function mutations in the ryanodine receptor type 1 (RyR1) gene (chromosome 19q13). Triggering agents cause uncontrolled calcium release from the SR, leading to sustained muscle contraction, hyperthermia, acidosis, hyperkalaemia, and rhabdomyolysis. Treatment is dantrolene, which blocks RyR1.','universal',true,'{year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Muscle Contraction Mechanism','easy','mcq','Muscle relaxation following contraction is primarily accomplished by:','["A. Active pumping of calcium back into the sarcoplasmic reticulum by SERCA (SR Ca2+-ATPase)","B. Passive diffusion of calcium out of the cytoplasm across the sarcolemma","C. Re-uptake of calcium by troponin C after the power stroke","D. Inhibition of the ryanodine receptor by rising ADP concentrations"]','A','Relaxation requires reduction of cytoplasmic calcium below the troponin C binding threshold (~0.1 µM). This is achieved primarily by SERCA (sarcoplasmic/endoplasmic reticulum Ca2+-ATPase), which actively pumps calcium back into the SR at the cost of 2 Ca2+ per ATP. This restoration of low cytoplasmic calcium allows tropomyosin to re-cover the myosin binding sites on actin.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Muscle Fibre Types & Fatigue','easy','mcq','Type I muscle fibres (slow-twitch, oxidative) are characterised by:','["A. High glycolytic capacity, large diameter, and rapid contraction speed","B. High mitochondrial density, reliance on oxidative phosphorylation, and resistance to fatigue","C. High myosin ATPase activity, pale colour, and expression of fast myosin heavy chains","D. Low capillary density and primary use during explosive anaerobic activities"]','B','Type I fibres (slow oxidative) contain abundant mitochondria and myoglobin (giving them a red colour), are densely vascularised, and generate ATP primarily via oxidative phosphorylation. They express slow myosin heavy chain (MHC I), have low ATPase activity, contract slowly, and are highly resistant to fatigue — ideal for sustained postural and endurance activities.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Muscle Fibre Types & Fatigue','easy','mcq','Which muscle fibre type is most preferentially recruited during a 100-metre sprint?','["A. Type IIx (IIb) fibres","B. Type I fibres","C. Type IIa fibres","D. Type IIa and IIx fibres equally"]','A','Type IIx (formerly called IIb in humans) fibres are the fastest contracting, most powerful, and most glycolytic fibres. They are recruited for high-intensity, short-duration activities such as sprinting and heavy lifting. They fatigue rapidly due to limited oxidative capacity. Type I fibres are recruited first (Henneman''''s size principle), then IIa, then IIx.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Muscle Fibre Types & Fatigue','medium','mcq','According to Henneman''''s size principle of motor unit recruitment, which motor units are recruited first during increasing force generation?','["A. Large motor units innervating type IIx fibres, because they generate the most force","B. Small motor units innervating type I fibres, because their smaller motor neurons have lower firing thresholds","C. Motor units are recruited randomly regardless of size","D. Large-diameter motor neurons because they have lower input resistance and are more easily excited"]','B','Henneman''''s size principle states that motor units are recruited in order of increasing size: small α-motor neurons (low rheobase, high input resistance) innervating small type I motor units are recruited first at low force levels. As force requirements increase, progressively larger motor neurons and motor units (type IIa, then IIx) are recruited.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Muscle Fibre Types & Fatigue','medium','mcq','Type IIa fibres (fast-twitch, oxidative-glycolytic) differ from type IIx fibres in that they:','["A. Have faster myosin ATPase activity and lower oxidative capacity","B. Have intermediate oxidative capacity, are more fatigue-resistant than IIx, but less so than type I","C. Exclusively use glycolysis and contain no mitochondria","D. Are the primary fibre type in slow postural muscles such as the soleus"]','B','Type IIa fibres are intermediate: they express fast MHC (MHCIIa) with high ATPase activity but also have significant mitochondrial and oxidative capacity. They are more fatigue-resistant than IIx fibres but fatigue faster than type I. They are recruited during activities requiring moderate force for prolonged periods (e.g., middle-distance running).','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Muscle Fibre Types & Fatigue','medium','mcq','The primary mechanism of peripheral (muscular) fatigue during high-intensity exercise is:','["A. Accumulation of metabolic by-products (Pi, H+, ADP) that impair cross-bridge cycling and calcium handling","B. Failure of neural drive from the motor cortex to maintain motor unit firing rates","C. Depletion of acetylcholine at the neuromuscular junction","D. Inhibition of SERCA by rising lactic acid concentrations"]','A','During high-intensity exercise, inorganic phosphate (Pi) accumulates from ATP hydrolysis and impairs the power stroke and SR calcium release. Acidosis (H+ accumulation) and ADP also contribute. While lactate itself is not causally toxic, the associated ionic changes impair excitation-contraction coupling and cross-bridge force production.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Muscle Fibre Types & Fatigue','medium','mcq','Endurance training induces which of the following adaptations in skeletal muscle?','["A. Conversion of type I fibres to type IIx fibres to improve sprint speed","B. Hypertrophy of type IIx fibres with increased glycolytic enzyme activity","C. Increased mitochondrial density, capillary density, and myoglobin content","D. Decreased activity of citrate synthase and other oxidative enzymes"]','C','Endurance (aerobic) training causes mitochondrial biogenesis (mediated by PGC-1α), increased capillary density (improved oxygen delivery), and higher myoglobin content. There may also be a shift from type IIx to type IIa fibres. These adaptations enhance oxidative ATP production, improve lactate threshold, and increase fatigue resistance.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Muscle Fibre Types & Fatigue','hard','mcq','Delayed-onset muscle soreness (DOMS) typically peaks 24-72 hours after unaccustomed exercise and is primarily attributed to:','["A. Accumulation of lactic acid in muscle tissue causing chemical irritation of nociceptors","B. Rhabdomyolysis with myoglobin release causing direct tubular damage and pain","C. Eccentric exercise-induced micro-tears in myofibrils and connective tissue with subsequent inflammatory response","D. Central sensitisation of pain pathways by pro-inflammatory cytokines from fatigued motor neurons"]','C','DOMS results primarily from eccentric (lengthening) contractions, which generate high force with fewer active cross-bridges, causing mechanical micro-damage to sarcomeres and connective tissue. The subsequent inflammatory response (prostaglandins, bradykinin, cytokines) sensitises nociceptors. Lactic acid is cleared within 1 hour of exercise cessation and does not cause DOMS.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Muscle Fibre Types & Fatigue','hard','mcq','Which transcription coactivator is considered the master regulator of mitochondrial biogenesis in skeletal muscle?','["A. MyoD","B. NF-κB","C. PGC-1α (peroxisome proliferator-activated receptor gamma coactivator-1α)","D. FOXO3a"]','C','PGC-1α is activated by exercise, cold exposure, and caloric restriction. It co-activates nuclear respiratory factors (NRF-1, NRF-2) and oestrogen-related receptor α (ERRα), driving expression of nuclear-encoded mitochondrial genes and upregulation of TFAM (mitochondrial transcription factor A), which promotes mitochondrial DNA replication and transcription.','universal',true,'{year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Muscle Fibre Types & Fatigue','hard','mcq','In McArdle disease (glycogen storage disease type V), patients experience exercise intolerance and myalgia but paradoxically improve after an initial rest (the ''''second wind''''). The metabolic defect is:','["A. Absence of myophosphorylase preventing muscle glycogen breakdown, with FFA and blood glucose used after the second wind","B. Deficiency of acid maltase (alpha-1,4-glucosidase) causing lysosomal glycogen accumulation","C. Deficiency of carnitine palmitoyltransferase I preventing FFA entry into mitochondria","D. Absence of succinate dehydrogenase impairing the TCA cycle in muscle"]','A','McArdle disease is caused by myophosphorylase deficiency. Patients cannot mobilise muscle glycogen, leading to early fatigue and cramp. The ''''second wind'''' phenomenon occurs after ~8-10 minutes when increased cardiac output delivers more blood glucose and free fatty acids to working muscles, partially compensating for the glycogenolytic block.','universal',true,'{year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Muscle Fibre Types & Fatigue','easy','mcq','Which of the following is a correct statement about the soleus muscle?','["A. It contains predominantly type IIx fast-twitch glycolytic fibres","B. It is composed mainly of type I slow-twitch oxidative fibres, reflecting its role in sustained antigravity posture","C. It relies entirely on anaerobic glycolysis to sustain prolonged activity","D. It is innervated by motor units with low fatigue resistance and rapid contraction speed"]','B','The soleus is a classic slow-twitch postural muscle, composed of approximately 70-80% type I fibres. Its primary role in maintaining upright posture requires sustained, low-force, fatigue-resistant contractions for hours. In contrast, the gastrocnemius has a higher proportion of type II fibres and is used more for rapid movements like jumping.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Neuromuscular Junction','easy','mcq','Acetylcholine (ACh) is synthesised in the motor nerve terminal by the enzyme:','["A. Acetylcholinesterase","B. Monoamine oxidase","C. Butyrylcholinesterase","D. Choline acetyltransferase (ChAT)"]','D','Choline acetyltransferase (ChAT) catalyses the synthesis of ACh from choline and acetyl-CoA in the cytoplasm of the motor nerve terminal. ChAT is a marker for cholinergic neurons. Acetylcholinesterase (AChE) terminates ACh action by hydrolysing it to choline and acetate in the synaptic cleft.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Neuromuscular Junction','easy','mcq','After ACh is hydrolysed in the neuromuscular junction, the choline product is:','["A. Excreted in the urine","B. Taken up by the presynaptic terminal via a high-affinity choline transporter for ACh resynthesis","C. Diffused away and lost from the synaptic cleft","D. Directly converted to acetylcholine in the synaptic cleft"]','B','The choline produced by AChE hydrolysis of ACh is recaptured by the presynaptic terminal via a sodium-dependent, high-affinity choline transporter (CHT1), the rate-limiting step in ACh synthesis. This recycling is essential for sustained cholinergic transmission. Hemicholinium-3 blocks this transporter and depletes ACh stores.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Neuromuscular Junction','medium','mcq','The end-plate potential (EPP) generated at the neuromuscular junction is:','["A. A large depolarisation caused by ACh opening nicotinic receptors permeable to Na+ and K+, reliably triggering a muscle action potential","B. A hyperpolarising inhibitory potential similar to IPSPs in the CNS","C. A graded potential that only triggers muscle contraction if summed with other EPPs","D. Generated by muscarinic ACh receptors coupled to G proteins"]','A','The EPP is generated when ACh binds to nicotinic ACh receptors (nAChRs — ligand-gated ion channels permeable to Na+ and K+). The net inward sodium current causes a large depolarisation. At the NMJ, a single nerve impulse releases enough ACh to generate an EPP well above the threshold for a muscle action potential (safety factor ~5-fold).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Neuromuscular Junction','medium','mcq','Myasthenia gravis is an autoimmune disease characterised by fatigable muscle weakness. The primary pathological mechanism is:','["A. Antibodies against voltage-gated calcium channels at the presynaptic terminal, reducing ACh release","B. Deficiency of choline acetyltransferase causing reduced ACh synthesis","C. Antibodies against postsynaptic nicotinic ACh receptors, reducing their number and causing complement-mediated end-plate destruction","D. Autoimmune destruction of alpha motor neurons in the anterior horn of the spinal cord"]','C','In myasthenia gravis (MG), IgG autoantibodies (mainly anti-AChR) bind nicotinic AChRs, causing receptor internalisation, complement-mediated destruction of the end-plate, and competitive blockade. This reduces the safety factor at the NMJ, causing fatigable weakness that worsens with use. Treatment includes AChE inhibitors (pyridostigmine) and immunosuppression.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Neuromuscular Junction','medium','mcq','Lambert-Eaton myasthenic syndrome (LEMS) differs from myasthenia gravis in that it:','["A. Causes weakness that improves with repeated activity, and is caused by anti-VGCC antibodies reducing ACh release","B. Is caused by anti-AChR antibodies causing postsynaptic receptor loss","C. Preferentially affects ocular and bulbar muscles and is associated with thymoma","D. Is treated primarily with acetylcholinesterase inhibitors which produce dramatic improvement"]','A','LEMS is caused by IgG antibodies against presynaptic P/Q-type voltage-gated calcium channels (VGCCs), reducing ACh vesicle exocytosis. Weakness paradoxically improves with repetitive stimulation (facilitating calcium build-up). LEMS is a paraneoplastic syndrome (associated with small-cell lung cancer in ~60%) or autoimmune. Autonomic dysfunction and absent reflexes (post-tetanic potentiation) are distinguishing features.','universal',true,'{year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Neuromuscular Junction','medium','mcq','Botulinum toxin causes flaccid paralysis by:','["A. Irreversibly blocking postsynaptic nicotinic ACh receptors","B. Cleaving SNARE proteins (SNAP-25, synaptobrevin, syntaxin) required for ACh vesicle fusion with the presynaptic membrane","C. Inhibiting choline acetyltransferase and depleting ACh stores","D. Causing persistent depolarisation of the motor end plate by mimicking ACh action"]','B','Botulinum toxin (BTX) is a zinc-dependent endoprotease that cleaves SNARE complex proteins (serotypes A and E cleave SNAP-25; B, D, F cleave synaptobrevin/VAMP; C cleaves syntaxin and SNAP-25). These proteins are essential for fusion of ACh-containing vesicles with the presynaptic membrane, so BTX causes flaccid paralysis by blocking ACh release.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Neuromuscular Junction','hard','mcq','Organophosphate poisoning (e.g., nerve agents, insecticides) causes the SLUDGE syndrome and muscle fasciculations because:','["A. Organophosphates directly activate nicotinic and muscarinic ACh receptors","B. Organophosphates block voltage-gated sodium channels in motor neurons","C. Irreversible inhibition of acetylcholinesterase leads to ACh accumulation at all cholinergic synapses","D. They stimulate excess ACh release from presynaptic terminals at both NMJ and autonomic ganglia"]','C','Organophosphates irreversibly phosphorylate the serine residue in the active site of AChE, preventing ACh hydrolysis. ACh accumulates at muscarinic synapses (causing SLUDGE: salivation, lacrimation, urination, defaecation, GI distress, emesis), and nicotinic NMJ synapses (fasciculations → paralysis) and CNS. Treatment: atropine (muscarinic) + pralidoxime (AChE reactivation if given early).','universal',true,'{year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Neuromuscular Junction','hard','mcq','The postsynaptic nicotinic ACh receptor at the neuromuscular junction is a pentameric ion channel. What is its subunit composition in adult human skeletal muscle?','["A. 2α, 1β, 1γ, 1δ","B. 2α, 2β, 1δ","C. 2α, 1β, 1δ, 1ε","D. 3α, 1β, 1δ"]','C','The adult NMJ nAChR is a pentamer composed of 2α1, 1β1, 1δ, and 1ε subunits (replacing the foetal γ subunit which is present in utero). ACh must bind to both α subunits simultaneously to open the ion channel. The ε subunit replaces γ after birth, conferring different channel kinetics (faster, shorter openings) in adult muscle.','universal',false,'{year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Neuromuscular Junction','hard','mcq','Succinylcholine causes a depolarising neuromuscular blockade characterised by initial fasciculations followed by paralysis. This occurs because:','["A. It acts as a non-hydrolysable ACh agonist, causing sustained end-plate depolarisation and inactivation of adjacent sodium channels","B. It competitively antagonises ACh at the postsynaptic nAChR, producing flaccid paralysis without initial fasciculations","C. It blocks presynaptic VGCC, reducing ACh vesicle release without initial muscle activity","D. It irreversibly crosslinks nAChR subunits in an open conformation"]','A','Succinylcholine (suxamethonium) mimics ACh at the nAChR but is resistant to AChE hydrolysis. It causes sustained end-plate depolarisation (Phase I block), which initially generates fasciculations then paralyses muscle because adjacent voltage-gated Na+ channels enter inactivation and cannot generate action potentials. With prolonged exposure, a desensitisation block (Phase II) may develop.','universal',true,'{year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Neuromuscular Junction','easy','mcq','ACh is packaged into synaptic vesicles at the motor nerve terminal by the transporter:','["A. Choline acetyltransferase (ChAT)","B. SNAP-25","C. Vesicular ACh transporter (VAChT)","D. Synaptotagmin"]','C','The vesicular acetylcholine transporter (VAChT) packages ACh from the cytoplasm into synaptic vesicles using the proton electrochemical gradient. Vesamicol blocks VAChT. SNAP-25 and syntaxin are SNARE proteins involved in vesicle fusion; synaptotagmin is the calcium sensor that triggers vesicle exocytosis when calcium concentration rises in the terminal.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Joint Anatomy','easy','mcq','Which of the following is a characteristic feature exclusive to synovial joints?','["A. A joint cavity lined by synovial membrane and filled with synovial fluid","B. A fibrous articular capsule","C. Hyaline cartilage covering the bone ends","D. Ligamentous reinforcement of the joint"]','A','The defining feature of synovial (diarthrodial) joints is a joint cavity lined by synovial membrane (synovium) containing synovial fluid. Other features (capsule, cartilage, ligaments) may be present to varying degrees in other joint types. Synovial fluid lubricates and nourishes the avascular articular cartilage.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Joint Anatomy','easy','mcq','The pubic symphysis is an example of which type of joint?','["A. Cartilaginous joint (symphysis — secondary cartilaginous joint)","B. Synovial joint","C. Fibrous joint (syndesmosis)","D. Cartilaginous joint (synchondrosis — primary cartilaginous joint)"]','A','The pubic symphysis is a secondary cartilaginous joint (symphysis) where the articulating surfaces are covered by hyaline cartilage and united by a fibrocartilage disc. Symphyses permit limited movement and are found at the pubic symphysis, intervertebral discs, and manubriosternal joint. Synchondroses (primary cartilaginous joints) unite with hyaline cartilage only.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Joint Anatomy','medium','mcq','Synovial fluid is produced by the synovial membrane and its primary function is to:','["A. Lubricate the joint surface via weeping lubrication and nourish the avascular articular cartilage by diffusion","B. Absorb impact forces transmitted across the joint surface","C. Provide structural reinforcement of the joint by binding the opposing bone ends","D. Secrete immunoglobulins to protect the joint from infection"]','A','Synovial fluid (a dialysate of plasma plus hyaluronic acid secreted by type B synoviocytes) performs two key functions: (1) boundary lubrication of articular cartilage surfaces; and (2) nutritional support of the avascular articular cartilage via diffusion of oxygen, glucose, and metabolites during joint loading (''''weeping lubrication'''').','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Joint Anatomy','medium','mcq','The joint capsule of a synovial joint is composed of:','["A. Inner fibrous layer providing structural support and outer synovial membrane producing synovial fluid","B. Two layers of fibrocartilage with a central hyaluronic acid gel","C. Outer fibrous layer providing structural support and inner synovial membrane lining the joint cavity","D. Periosteum directly continuous with articular cartilage on both articulating surfaces"]','C','The articular capsule has an outer fibrous layer (dense irregular connective tissue providing tensile strength) and an inner synovial membrane layer. The synovial membrane (containing type A phagocytic macrophage-like synoviocytes and type B fibroblast-like cells) lines the capsule but does not cover articular cartilage or intra-articular discs.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Joint Anatomy','medium','mcq','Which of the following correctly classifies the knee joint?','["A. A simple synovial hinge joint with one pair of articulating surfaces","B. A ball-and-socket joint allowing multiaxial movement","C. A plane (gliding) joint allowing only translational movement in two axes","D. A compound synovial modified hinge joint with medial and lateral tibiofemoral and patellofemoral articulations"]','D','The knee is a compound synovial joint (multiple articulating surfaces within one capsule) classified as a modified hinge (ginglymus) joint. It includes medial and lateral tibiofemoral compartments and the patellofemoral joint. The medial and lateral menisci deepen the tibial plateau. Knee motion includes flexion/extension plus axial rotation (when flexed).','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Joint Anatomy','medium','mcq','In rheumatoid arthritis, the synovial membrane becomes hyperplastic forming a pannus. This pannus damages articular cartilage primarily by:','["A. Releasing proteases (MMPs, cathepsins) and pro-inflammatory cytokines (TNF-α, IL-1β) that degrade cartilage matrix","B. Directly secreting acid to dissolve hydroxyapatite in subchondral bone","C. Calcifying the cartilage surface, making it brittle and prone to fracture","D. Blocking diffusion of nutrients from synovial fluid to articular chondrocytes"]','A','Pannus is invasive synovial tissue driven by activated fibroblast-like synoviocytes and macrophages. It releases matrix metalloproteinases (MMP-1, 3, 13), cathepsins, and pro-inflammatory cytokines (TNF-α, IL-1β, IL-6) that degrade cartilage collagen and proteoglycans, and also stimulate osteoclast-mediated marginal erosions via RANKL upregulation.','universal',true,'{year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Joint Anatomy','hard','mcq','The cruciate ligaments of the knee are classified as intra-articular but extra-synovial. This means they are:','["A. Located within the joint cavity and lined by synovial membrane","B. Located completely outside the joint capsule and therefore not subject to haemarthrosis when torn","C. Within the joint cavity and directly bathed in synovial fluid","D. Located within the fibrous capsule but covered by synovial folds rather than directly bathed in synovial fluid"]','D','The cruciate ligaments are within the fibrous capsule (intra-articular) but are covered by a reflection of synovial membrane (extra-synovial), meaning they are not directly in the synovial space. They are therefore bathed in synovial fluid indirectly. Rupture of the ACL can still cause haemarthrosis because the ligament has its own blood supply.','universal',false,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Joint Anatomy','hard','mcq','Gout causes joint inflammation when:','["A. Antibodies against articular cartilage activate complement within the joint","B. Monosodium urate crystals are phagocytosed by synovial macrophages and neutrophils, triggering NLRP3 inflammasome activation and IL-1β release","C. Uric acid directly dissolves articular cartilage through chemical erosion","D. Hyperuricaemia activates complement via the alternative pathway within synovial fluid"]','B','In gout, supersaturated monosodium urate (MSU) crystallises in joints. MSU crystals are phagocytosed by macrophages and neutrophils. Within the cell, they activate the NLRP3 inflammasome, leading to caspase-1 activation and IL-1β secretion. This drives the intense acute inflammatory arthritis. Colchicine disrupts microtubules and inhibits neutrophil migration.','universal',true,'{year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Joint Anatomy','hard','mcq','A first metatarsophalangeal (MTP) joint aspiration in suspected gout would reveal crystals that are:','["A. Positively birefringent, rhomboid-shaped crystals of calcium pyrophosphate dihydrate (CPPD)","B. Positively birefringent, needle-shaped monosodium urate crystals under compensated polarised light","C. Non-birefringent calcium oxalate crystals in a background of neutrophils","D. Negatively birefringent, needle-shaped monosodium urate crystals under compensated polarised light"]','D','Monosodium urate crystals appear needle-shaped and are negatively birefringent (yellow when parallel to the slow vibration direction of the compensator). CPPD crystals (pseudogout) are positively birefringent (blue when parallel), rhomboid/rod-shaped. The MTP of the great toe is the classic site for gout (podagra).','universal',true,'{year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Joint Anatomy','easy','mcq','A synchondrosis (primary cartilaginous joint) is characterised by:','["A. Hyaline cartilage uniting the two bony surfaces, usually a temporary joint that eventually ossifies","B. A fibrocartilage disc uniting two bones covered with hyaline cartilage","C. Dense fibrous connective tissue only, without any cartilaginous component","D. A synovial cavity with freely moveable articular surfaces"]','A','Synchondroses are primary cartilaginous joints where bones are united by hyaline cartilage. They are typically temporary (e.g., epiphyseal growth plates, costochondral junctions in childhood) and eventually ossify. The first sternocostal joint and spheno-occipital synchondrosis are permanent synchondroses in adults.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Tendons, Ligaments & Proprioception','easy','mcq','Muscle spindles (intrafusal fibres) detect:','["A. Changes in muscle length and velocity of length change","B. Force generated by the muscle during contraction","C. Metabolic by-products such as lactic acid during exercise","D. Pressure on the tendon at the musculotendinous junction"]','A','Muscle spindles are stretch receptors that detect changes in muscle length (static) and rate of length change (dynamic). The primary (Ia) afferents from nuclear bag fibres respond to both velocity and length; secondary (II) afferents from nuclear chain fibres primarily signal length. Muscle spindles are the basis of the stretch reflex.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Tendons, Ligaments & Proprioception','easy','mcq','Golgi tendon organs (GTOs) are located at the musculotendinous junction and signal via:','["A. Ia afferent fibres sensitive to muscle stretch","B. II afferent fibres sensitive to muscle length","C. III and IV afferent fibres sensitive to pain and metabolites","D. Ib afferent fibres sensitive to tension within the tendon"]','D','GTOs are encapsulated mechanoreceptors at the musculotendinous junction in series with the muscle. They are innervated by Ib afferent fibres and respond to tension (both passive stretch and active contraction). GTO activation inhibits the homonymous muscle (autogenic inhibition via Ib interneurons) and excites antagonist muscles.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Tendons, Ligaments & Proprioception','medium','mcq','The gamma (γ) motor neuron system maintains muscle spindle sensitivity during alpha motor neuron activation by:','["A. Increasing the firing threshold of Ia afferent fibres within the muscle spindle","B. Inhibiting Ia afferent firing from the spindle when the muscle shortens","C. Contracting intrafusal fibre ends (polar regions) to maintain nuclear bag/chain fibre tension during extrafusal shortening","D. Releasing acetylcholine onto the equatorial region of intrafusal fibres to activate them"]','C','When extrafusal muscle fibres shorten during contraction, muscle spindles would become slack and lose sensitivity. Gamma (γ) motor neurons co-activate with α motor neurons (alpha-gamma coactivation) to contract the polar (contractile) ends of intrafusal fibres, keeping the equatorial (sensory) region under tension and maintaining spindle sensitivity throughout movement.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Tendons, Ligaments & Proprioception','medium','mcq','Tendons predominantly contain which type of collagen, arranged how for maximum tensile strength?','["A. Type II collagen in a random meshwork providing multidirectional tensile strength","B. Type III collagen in loose connective tissue with fibroblasts for rapid remodelling","C. Type IV collagen in a sheet-like network providing resistance to shear forces","D. Type I collagen fibres arranged in parallel bundles along the line of tensile force"]','D','Tendons consist of approximately 70-80% dry weight type I collagen (primarily type I), organised in a hierarchical structure: tropocollagen molecules → microfibrils → fibrils → fascicles → the whole tendon. The parallel arrangement along the axis of force application maximises tensile strength and stiffness, transmitting force from muscle to bone efficiently.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Tendons, Ligaments & Proprioception','medium','mcq','Which afferent nerve fibre group is responsible for the dynamic component of the stretch reflex, responding to the rate of change of muscle length?','["A. Group Ib from Golgi tendon organs","B. Group II from secondary endings of nuclear chain fibres","C. Group Ia from primary endings of nuclear bag fibres in muscle spindles","D. Group III (Aδ) free nerve endings sensing mechanical stress"]','C','Group Ia afferents arise from primary (annulospiral) endings on both nuclear bag 1 (dynamic) and nuclear chain fibres. Nuclear bag 1 fibres are particularly sensitive to the rate of length change (dynamic response), while nuclear chain fibres and nuclear bag 2 fibres respond more to steady-state length. Group II afferents from secondary (flower-spray) endings signal static length.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Tendons, Ligaments & Proprioception','medium','mcq','Ligaments differ from tendons in that they:','["A. Are composed primarily of type II collagen and have higher elasticity","B. Are composed entirely of elastic fibres with no collagen component","C. Are more vascular than tendons and heal more rapidly after injury","D. Connect bone to bone, have a less organised (more variable fibre direction) collagen structure, and contain more elastin"]','D','Ligaments connect bone to bone and contain mainly type I collagen but with less parallel organisation than tendons (reflecting multidirectional loading requirements). They contain slightly more elastin than tendons. Ligaments are less vascular than muscles but more vascular than cartilage. Their healing after rupture is often incomplete, leading to joint instability.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Tendons, Ligaments & Proprioception','hard','mcq','The inverse myotatic reflex (autogenic inhibition) protects against excessive tendon tension. The reflex arc involves:','["A. Ia afferents → spinal cord → α motor neurons → homonymous muscle contraction","B. Ib afferents → inhibitory interneurons in the spinal cord → inhibition of α motor neurons to the homonymous muscle","C. II afferents → spinal cord → excitation of both agonist and antagonist α motor neurons","D. Ib afferents → direct monosynaptic inhibition of α motor neurons without interneurons"]','B','The autogenic inhibition reflex: Ib afferents from GTOs project to the spinal cord and synapse on inhibitory Ib interneurons. These interneurons hyperpolarise homonymous α motor neurons, reducing muscle force. This protects against tendon rupture. Simultaneously, Ib interneurons may excite antagonist muscles. This is the physiological basis for the ''''clasp-knife'''' phenomenon in spasticity.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Tendons, Ligaments & Proprioception','hard','mcq','Proprioception, the sense of joint position and movement, is particularly dependent on afferent input from:','["A. Cutaneous Merkel discs and Ruffini corpuscles only","B. Only Golgi tendon organs within tendons at each joint","C. A combination of muscle spindles (Ia and II), Golgi tendon organs (Ib), joint mechanoreceptors, and cutaneous receptors","D. Free nerve endings (group III and IV) sensitive to joint position"]','C','Proprioception integrates input from multiple receptor types: muscle spindles (Ia and II afferents — primary source of limb position sense), GTOs (Ib afferents — force sensing), joint capsule mechanoreceptors (Ruffini endings, Pacinian corpuscles), and cutaneous receptors. Disruption of spindle afferents (e.g., tabes dorsalis) causes profound ataxia demonstrating their central role.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Tendons, Ligaments & Proprioception','hard','mcq','In Achilles tendinopathy (tendinosis), the histological hallmark is:','["A. Dense neutrophil infiltration and fibrin exudate indicating acute inflammation","B. Granulomatous inflammation with multinucleated giant cells and central necrosis","C. Complete tendon rupture with haematoma formation and loss of tendon continuity","D. Angiofibroblastic degeneration with disorganised collagen, mucoid ground substance, and neovascularisation without inflammatory cells"]','D','Chronic Achilles tendinopathy (tendinosis) shows angiofibroblastic degeneration: disorganised collagen fibres (loss of normal parallel arrangement), increased mucoid ground substance, hypercellularity of fibroblasts, and pathological neovascularisation. Inflammatory cells are conspicuously absent, distinguishing it from tendinitis. This explains the poor response to anti-inflammatory drugs.','universal',true,'{year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Tendons, Ligaments & Proprioception','easy','mcq','The knee jerk (patellar tendon reflex) is a monosynaptic reflex that involves:','["A. A disynaptic pathway through the spinal cord interneurons","B. Ib afferents from patellar tendon GTOs driving quadriceps contraction","C. Descending corticospinal tract fibres modulating local motor neurons","D. Direct Ia afferent fibres from the quadriceps spindles synapsing on L3/L4 quadriceps α motor neurons"]','D','The patellar reflex is a monosynaptic stretch reflex: tapping the patellar tendon stretches the quadriceps, activating Ia afferents from quadriceps muscle spindles. These afferents directly (monosynaptically) excite L3/L4 quadriceps α motor neurons, causing quadriceps contraction. Simultaneously, reciprocal inhibition (via Ia inhibitory interneurons) relaxes the hamstrings.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Bone Metabolism & Calcium Regulation','easy','mcq','Parathyroid hormone (PTH) acts on bone to:','["A. Directly stimulate osteoclast activity to increase calcium resorption from bone","B. Inhibit osteoclast differentiation and reduce serum calcium","C. Act on osteoblasts (which express PTH receptors), inducing RANKL expression to indirectly stimulate osteoclast-mediated bone resorption","D. Deposit calcium into bone by promoting osteoblast activity exclusively"]','C','PTH receptors (PTH1R) are expressed on osteoblasts, not osteoclasts. PTH binding to osteoblasts increases RANKL expression, which drives osteoclast differentiation and activation, leading to bone resorption and calcium release. Paradoxically, intermittent PTH (as in teriparatide therapy) promotes net bone formation by favouring osteoblast activity.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Bone Metabolism & Calcium Regulation','easy','mcq','The active form of vitamin D that regulates calcium absorption is:','["A. Vitamin D2 (ergocalciferol) from dietary sources","B. 1,25-dihydroxyvitamin D3 (calcitriol) produced by 1α-hydroxylase in the kidney","C. 25-hydroxyvitamin D3 (calcidiol) produced in the liver","D. 7-dehydrocholesterol produced in the skin under UV light"]','B','1,25-dihydroxyvitamin D3 (calcitriol) is the biologically active form. It is produced by 25-hydroxyvitamin D-1α-hydroxylase (CYP27B1) in the kidney proximal tubule, stimulated by PTH, hypocalcaemia, and hypophosphataemia. Calcitriol binds to the nuclear vitamin D receptor (VDR) to upregulate intestinal calcium and phosphate absorption.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Bone Metabolism & Calcium Regulation','medium','mcq','Calcitonin, secreted by parafollicular C cells of the thyroid, lowers serum calcium by:','["A. Inhibiting PTH secretion from the parathyroid glands","B. Directly inhibiting osteoclast activity, reducing bone resorption","C. Blocking the action of vitamin D on intestinal calcium absorption","D. Increasing renal calcium excretion by blocking calcium reabsorption in the loop of Henle"]','B','Calcitonin inhibits osteoclast activity via calcitonin receptors on osteoclasts, reducing bone resorption and lowering serum calcium. Its physiological significance in humans is debated as patients after thyroidectomy have normal calcium homeostasis. Calcitonin has clinical uses in Paget''''s disease and hypercalcaemia of malignancy.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Bone Metabolism & Calcium Regulation','medium','mcq','PTH increases serum calcium through which renal mechanism?','["A. Decreasing GFR to reduce calcium filtration","B. Blocking calcium reabsorption in the proximal convoluted tubule","C. Activating the sodium-calcium exchanger in the collecting duct","D. Stimulating calcium reabsorption in the distal convoluted tubule (DCT) and thick ascending limb"]','D','PTH acts on the DCT and thick ascending limb to increase transcellular calcium reabsorption via upregulation of TRPV5 channels (apical) and NCX1/PMCA (basolateral). PTH also stimulates 1α-hydroxylase to produce calcitriol (increasing intestinal absorption) and promotes bone resorption, together raising serum calcium.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Bone Metabolism & Calcium Regulation','medium','mcq','Primary hyperparathyroidism typically presents with which combination of biochemical findings?','["A. High PTH, low serum calcium, high phosphate, low urinary calcium","B. Low PTH, high serum calcium, high phosphate, low urinary calcium","C. Normal PTH, high serum calcium, normal phosphate — consistent with familial hypocalciuric hypercalcaemia","D. High PTH, high serum calcium, low phosphate, high urinary calcium (if not compensated)"]','D','Primary hyperparathyroidism (usually from a solitary parathyroid adenoma) causes autonomous PTH secretion: elevated PTH drives hypercalcaemia (bone resorption + renal Ca reabsorption + calcitriol synthesis) and hypophosphataemia (reduced tubular phosphate reabsorption — PTH inhibits Na-Pi co-transporter). Urinary calcium may be elevated despite tubular reabsorption if filtered load is very high.','universal',true,'{year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Bone Metabolism & Calcium Regulation','medium','mcq','Vitamin D deficiency in children causes rickets, characterised by:','["A. Failure of osteoid mineralisation, resulting in soft, deformable bones and characteristic skeletal deformities","B. Increased bone density with pathological fractures due to brittle bone disease","C. Premature fusion of growth plates leading to short stature","D. Osteoclast overactivity with subperiosteal bone resorption and cyst formation"]','A','Vitamin D deficiency reduces intestinal calcium and phosphate absorption, causing secondary hyperparathyroidism. Insufficient mineral substrate prevents mineralisation of osteoid (bone matrix), producing unmineralised osteoid that is soft and deformable. This manifests as bowing of long bones, frontal bossing, rachitic rosary (costochondral junction enlargement), and delayed fontanelle closure in children.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Bone Metabolism & Calcium Regulation','hard','mcq','FGF-23 (fibroblast growth factor 23) is secreted by osteocytes in response to elevated phosphate and acts to:','["A. Increase renal phosphate reabsorption and stimulate 1α-hydroxylase activity to raise calcitriol","B. Directly suppress PTH secretion without affecting renal phosphate handling","C. Decrease renal phosphate reabsorption by downregulating NaPi-IIa/IIc transporters and inhibit 1α-hydroxylase, reducing calcitriol","D. Promote osteoblast differentiation and increase bone mineralisation by elevating local phosphate"]','C','FGF-23 (acting with its co-receptor Klotho) inhibits NaPi-IIa and NaPi-IIc sodium-phosphate co-transporters in the proximal tubule, increasing phosphate excretion. It also inhibits renal 1α-hydroxylase (reducing calcitriol synthesis) and stimulates 24-hydroxylase (inactivating vitamin D). FGF-23 excess causes X-linked hypophosphataemia (XLH) and tumour-induced osteomalacia.','universal',true,'{year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Bone Metabolism & Calcium Regulation','hard','mcq','Hypocalcaemia in the setting of chronic kidney disease (CKD-MBD) results from a combination of:','["A. Excessive PTH inactivation by the diseased kidneys and loss of PTH receptor sensitivity in bone","B. Excess calcitonin secretion by the kidneys in response to rising phosphate levels","C. Loss of calcium in the urine due to failure of tubular reabsorption in damaged nephrons","D. Reduced 1α-hydroxylase activity (less calcitriol, reduced intestinal Ca absorption), hyperphosphataemia (calcium-phosphate complex formation), and skeletal resistance to PTH"]','D','CKD-MBD involves: (1) reduced functional nephron mass → decreased 1α-hydroxylase → less calcitriol → reduced intestinal calcium and phosphate absorption; (2) reduced GFR → phosphate retention → hyperphosphataemia → chelation of calcium; (3) uraemia-induced skeletal resistance to PTH. The result is hypocalcaemia despite secondary hyperparathyroidism.','universal',true,'{year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Bone Metabolism & Calcium Regulation','hard','mcq','Bisphosphonates chelate calcium in bone and are taken up by osteoclasts during bone resorption. Their primary intracellular mechanism of action is:','["A. Inhibition of farnesyl pyrophosphate synthase in the mevalonate pathway, preventing protein prenylation and inducing osteoclast apoptosis","B. Inhibition of carbonic anhydrase II, reducing acidification of the resorption lacuna","C. Activation of the calcitonin receptor, mimicking calcitonins inhibitory effect on osteoclasts","D. Direct binding to hydroxyapatite and rendering the mineral surface resistant to osteoclast-mediated dissolution"]','A','Nitrogen-containing bisphosphonates (alendronate, risedronate, zoledronate) are internalised by osteoclasts during bone resorption. Intracellularly, they inhibit farnesyl pyrophosphate synthase, a key enzyme of the mevalonate pathway. This prevents geranylgeranylation of small GTPases (Rac, Rho, Rab) essential for osteoclast cytoskeletal organisation and survival, inducing apoptosis.','universal',true,'{year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Bone Metabolism & Calcium Regulation','easy','mcq','The normal range of total serum calcium in adults is approximately:','["A. 1.0-1.5 mmol/L","B. 3.0-3.5 mmol/L","C. 2.2-2.6 mmol/L","D. 4.0-4.5 mmol/L"]','C','Normal total serum calcium is 2.2-2.6 mmol/L (8.8-10.4 mg/dL). Approximately 40-45% is protein-bound (mainly albumin), 10% is complexed with anions (citrate, phosphate), and 45-50% is ionised (the physiologically active fraction, ~1.15-1.30 mmol/L). Calcium regulation is tightly controlled by PTH, calcitriol, and calcitonin.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Exercise Physiology & MSK Adaptations','easy','mcq','VO2max (maximal oxygen uptake) is the gold-standard measure of aerobic capacity and is primarily limited by:','["A. Lung diffusion capacity for oxygen","B. Skeletal muscle mitochondrial density alone","C. The ability of haemoglobin to release oxygen to exercising tissues","D. Cardiac output (maximal heart rate × stroke volume) and oxygen-carrying capacity of blood"]','D','VO2max is primarily limited by central cardiovascular factors (cardiac output = HR × SV) rather than peripheral factors in most individuals. The Fick equation: VO2 = CO × (CaO2 - CvO2). Elite endurance athletes have large stroke volumes (eccentric cardiac hypertrophy), high maximum cardiac outputs, and high capillary densities. Peripheral limitations (mitochondria, diffusion capacity) may become rate-limiting with specific training.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Exercise Physiology & MSK Adaptations','easy','mcq','Skeletal muscle hypertrophy in response to resistance training primarily results from:','["A. An increase in the cross-sectional area of individual muscle fibres due to increased myofibril content","B. An increase in the number of muscle fibres (hyperplasia)","C. Conversion of type I fibres to type IIx fibres","D. Increased glycogen storage in existing muscle fibres"]','A','Resistance training-induced hypertrophy occurs primarily through increases in fibre cross-sectional area, driven by net protein synthesis exceeding protein degradation. This involves addition of sarcomeres in parallel (myofibril splitting and addition), activated by mechanical stimuli via mTORC1 signalling, satellite cell activation, and hormonal factors (IGF-1, testosterone). True hyperplasia (fibre number increase) is not established in humans.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Exercise Physiology & MSK Adaptations','medium','mcq','The lactate threshold (anaerobic threshold) represents the exercise intensity at which:','["A. Blood lactate begins to accumulate disproportionately because lactate production exceeds clearance","B. Muscle switches entirely from aerobic to anaerobic ATP production","C. Glycogen stores are completely depleted in working muscles","D. Maximal cardiac output is achieved and cannot increase further with greater intensity"]','A','The lactate threshold is the exercise intensity above which blood lactate begins to rise non-linearly. At low intensities, lactate produced by working muscles is cleared by the liver, heart, and less active muscles. Beyond the threshold, production exceeds clearance. The threshold correlates with % VO2max that can be sustained and is an important predictor of endurance performance.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Exercise Physiology & MSK Adaptations','medium','mcq','During the first few seconds of maximal intensity exercise (e.g., 100m sprint), the primary energy source is:','["A. Aerobic oxidation of blood glucose","B. The phosphagen system — hydrolysis of stored ATP and phosphocreatine","C. Anaerobic glycolysis of muscle glycogen","D. Beta-oxidation of intramuscular triglycerides"]','B','The phosphagen (ATP-PCr) system provides immediate energy for the first 8-10 seconds of maximal exercise by hydrolysing stored ATP and using creatine kinase to regenerate ATP from phosphocreatine. This system has no oxygen requirement and no lactate production. After ~10 seconds, anaerobic glycolysis becomes the predominant source.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Exercise Physiology & MSK Adaptations','medium','mcq','Which molecular pathway is primarily responsible for initiating resistance exercise-induced muscle protein synthesis?','["A. AMP-activated protein kinase (AMPK) → PGC-1α → mitochondrial biogenesis","B. Mechanical load → PI3K/Akt/mTORC1 signalling → ribosomal S6 kinase activation → increased protein synthesis","C. IL-6 secretion → JAK-STAT3 pathway → myostatin upregulation","D. Calcineurin → NFAT → MyoD pathway preferentially in type II fibres"]','B','Resistance exercise activates mechanosensitive pathways, including PI3K → PDK1 → Akt phosphorylation → mTORC1 activation. mTORC1 phosphorylates S6 kinase 1 (p70S6K) and 4E-BP1, increasing ribosomal biogenesis and translation initiation. IGF-1 (local and systemic) potentiates Akt/mTOR. Leucine-rich amino acids also directly activate mTORC1.','universal',true,'{year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Exercise Physiology & MSK Adaptations','medium','mcq','Following a resistance training programme, muscle strength gains in the first 4-6 weeks occur primarily through:','["A. Significant increases in muscle fibre cross-sectional area and hypertrophy","B. Neural adaptations — increased motor unit recruitment, improved synchronisation, and reduced co-contraction of antagonists","C. Conversion of type I to type IIx fibres increasing rate of force development","D. Satellite cell proliferation and fusion increasing total muscle fibre number"]','B','Early strength gains (first 4-6 weeks) are predominantly neurological: improved motor unit recruitment (activating more motor units), enhanced discharge rate, better intermuscular coordination, and reduced antagonist co-contraction. Measurable hypertrophy requires 6-8 weeks of progressive resistance training to become the dominant mechanism.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Exercise Physiology & MSK Adaptations','hard','mcq','The ''''repeated bout effect'''' describes the phenomenon whereby a second bout of eccentric exercise causes less muscle damage and DOMS than the first. The primary protective mechanism is:','["A. Increased antioxidant enzyme activity preventing free radical damage in subsequent bouts","B. Selective apoptosis of susceptible type IIx fibres, with replacement by more fatigue-resistant type I fibres","C. Upregulation of heat shock proteins (HSPs) alone, which prevent protein denaturation","D. Structural remodelling of the sarcomere (addition of sarcomeres in series, increased titin expression) reducing mechanical strain during subsequent eccentric loading"]','D','The repeated bout effect involves multiple adaptations. The primary mechanism is sarcomere addition in series during the repair process (sarcomere number increases), shifting the optimum length of the muscle to longer lengths where eccentric forces are greater, thus reducing mechanical stress per sarcomere. Titin isoform changes and increased connective tissue stiffness also contribute.','universal',true,'{year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Exercise Physiology & MSK Adaptations','hard','mcq','Aerobic exercise training causes eccentric cardiac hypertrophy (athlete''''s heart). How does this differ from the pathological concentric hypertrophy of hypertensive heart disease?','["A. Eccentric hypertrophy involves ventricular dilation (increased end-diastolic volume) with proportional wall thickening; concentric involves wall thickening without increased chamber volume","B. Eccentric hypertrophy involves ventricular wall thickening without chamber enlargement; concentric involves chamber dilation with normal wall thickness","C. Both are identical morphologically but eccentric hypertrophy is associated with preserved diastolic function","D. Eccentric hypertrophy is limited to the right ventricle in response to increased preload from exercise"]','A','Athlete''''s heart (eccentric hypertrophy) is characterised by increased ventricular cavity volume (enhanced preload adaptation) with proportional wall thickening, preserving normal wall-to-cavity ratio. This increases stroke volume. Pathological concentric hypertrophy (pressure overload — hypertension, AS) shows wall thickening with normal or reduced cavity volume, increased wall-to-cavity ratio, and impaired diastolic compliance.','universal',true,'{year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Exercise Physiology & MSK Adaptations','hard','mcq','Rhabdomyolysis, presenting with myalgia, weakness, and dark urine, causes acute kidney injury primarily through:','["A. Myoglobin-induced tubular toxicity (free radical generation, lipid peroxidation), tubular obstruction by myoglobin-Tamm-Horsfall protein casts, and renal vasoconstriction","B. Direct immune complex deposition in the glomerulus triggered by muscle protein antigens","C. Hyperkalaemia-induced renal tubular acidosis impairing the concentrating mechanism","D. Uric acid crystal deposition in tubules following massive purine release from necrotic muscle cells"]','A','Rhabdomyolysis causes AKI through three mechanisms: (1) myoglobin (in acid urine) is directly toxic to proximal tubular cells via free radical generation; (2) myoglobin precipitates with Tamm-Horsfall protein forming tubular casts, causing obstruction; (3) hypovolaemia and renal vasoconstriction (endothelin, catecholamines) reduce GFR. Treatment: aggressive IV fluid hydration to achieve >200 mL/hr urine output.','universal',true,'{year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Exercise Physiology & MSK Adaptations','easy','mcq','Which hormone is the primary anabolic driver of muscle hypertrophy in males undergoing resistance training?','["A. Cortisol","B. Insulin","C. Growth hormone acting alone without IGF-1 mediation","D. Testosterone"]','D','Testosterone (and its more potent metabolite dihydrotestosterone, DHT) is the primary anabolic androgen promoting muscle protein synthesis and satellite cell activation. It binds the androgen receptor, increasing transcription of muscle structural proteins. Males have 10-20-fold higher testosterone than females, explaining the greater hypertrophic response to resistance training. Growth hormone also contributes mainly via IGF-1 production.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');